; GEMS cmd $00 gemsnoteon(channel, note)
gems_note_on:
                jsr     init_cmd_fifo_z80(pc)
                moveq   #0,d0
                bra.s   gems_com2arg
; End of function gems_note_on


; GEMS cmd $01 gemsnoteoff(channel, note)
gems_note_off:
                jsr     init_cmd_fifo_z80(pc)
